arguments.command:
python3 -I -c "import json,re,collections
b='/user/user1/autorlbench-runs/20261122015303-59096-207c/workspace/results/grpo_gsm8k/'
def ex(s):
    a=re.findall(r'(-?[0-9.,]+)',s[-300:])
    f=None
    for f in reversed(a):
        if f not in ('','.'): break
    return f
def tolok(r):
    f=ex(r['output'])
    return f is not None and f.rstrip('.').replace(',','')==str(r['gts'])
m=lambda x: round(sum(float(r['score']) for r in x)/max(1,len(x)),3)
for st in (1,25,50):
    R=[json.loads(l) for l in open(b+'rollouts/%d.jsonl'%st)]
    n=len(R)
    g=collections.defaultdict(list)
    for r in R: g[r['input']].append(float(r['score']))
    mism=sum(1 for r in R if float(ex(r['output'])==str(r['gts']))!=float(r['score']))
    fn=sum(1 for r in R if tolok(r) and float(r['score'])==0)
    hs=[r for r in R if '####' in r['output']]
    nh=[r for r in R if '####' not in r['output']]
    sh=[r for r in R if len(r['output'])<120]
    print('rollout',st,'n',n,'mean',m(R),'groups',len(g),'allzero',sum(1 for v in g.values() if sum(v)==0),'allone',sum(1 for v in g.values() if sum(v)==len(v)),'scoremismatch',mism,'dotFN',fn)
    print('  hash',len(hs),m(hs),'nohash',len(nh),m(nh),'short',len(sh),m(sh),'meanchars',round(sum(len(r['output']) for r in R)/n))
V={}
for st in (0,25,50):
    V[st]={}
    for l in open(b+'val_generations/%d.jsonl'%st):
        r=json.loads(l)
        V[st][r['input']]=r
    R=list(V[st].values())
    n=len(R)
    print('val',st,n,'score',m(R),'tolerant',round(sum(1 for r in R if tolok(r))/n,4),'meanchars',round(sum(len(r['output']) for r in R)/n),'nohash',sum(1 for r in R if '####' not in r['output']))
for a,c in ((0,25),(0,50),(25,50)):
    ks=[k for k in V[a] if k in V[c]]
    print('val',a,'to',c,'common',len(ks),'identical',sum(1 for k in ks if V[a][k]['output']==V[c][k]['output']),'up',sum(1 for k in ks if float(V[c][k]['score'])>float(V[a][k]['score'])),'down',sum(1 for k in ks if float(V[c][k]['score'])<float(V[a][k]['score'])))
"

